  `cfg_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '配置版本',
  `created_at` datetime(3) NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '入库时间',
  PRIMARY KEY (`id`, `ts_ms`) USING BTREE,
  INDEX `idx_kind_sub_ts`(`data_kind` ASC, `data_sub` ASC, `ts_ms` ASC) USING BTREE,
  INDEX `idx_src_ts`(`src_kind` ASC, `src_param` ASC, `ts_ms` ASC) USING BTREE,
  INDEX `idx_ts`(`ts_ms` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 433859 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '遥测帧永久归档' ROW_FORMAT = Dynamic PARTITION BY RANGE (`ts_ms`)
